{% load static %}
{% load grandchallenge_tags %}
{% load sentry_public_dsn from raven %}
{% load placeFavicon from favtags %}
{% load url from grandchallenge_tags %}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    {% block html_header %}
        <meta http-equiv='Content-Type' content='text/html; charset=utf-8'>
        <meta name="description"
              content="{{ site.description }}"/>
        <meta name="keywords"
              content="open, science, medical, image, computing, validated"/>

        {% comment %}
            <script src="https://cdn.ravenjs.com/3.23.2/raven.min.js"
                    crossorigin="anonymous"></script>
            <script>Raven.config('{% sentry_public_dsn %}').install()</script>
        {% endcomment %}

        <!-- Global Site Tag (gtag.js) - Google Analytics -->
        <script async
                src="https://www.googletagmanager.com/gtag/js?id={{ google_analytics_id }}"></script>
        <script>
            window.dataLayer = window.dataLayer || [];

            function gtag() {
                dataLayer.push(arguments);
            }

            gtag('js', new Date());

            gtag('config', "{{ google_analytics_id }}");
        </script>

        {% block jquery_js %}
            <script type="text/javascript"
                    src="{% static "jquery-3.2.1/js/jquery-3.2.1.min.js" %}"></script>
            {# jquery ui must be before bootstrap, but is required by blueimp-file-upload #}
            <script src="https://code.jquery.com/ui/1.12.1/jquery-ui.min.js"
                    integrity="sha256-VazP97ZCwtekAsvgPBSUwPFKdrwD3unUfSGVYrahUqU="
                    crossorigin="anonymous"></script>
        {% endblock %}

        {% block bootstrap %}
            {# Latest compiled and minified CSS #}
            <link rel="stylesheet"
                  href="https://stackpath.bootstrapcdn.com/bootstrap/4.1.3/css/bootstrap.min.css"
                  integrity="sha384-MCw98/SFnGE8fJT3GXwEOngsV7Zt27NXFoaoApmYm81iuXoPkFOJwJ8ERdknLPMO"
                  crossorigin="anonymous">

            <script src="https://cdnjs.cloudflare.com/ajax/libs/popper.js/1.14.3/umd/popper.min.js"
                    integrity="sha384-ZMP7rVo3mIykV+2+9J3UJ46jBk0WLaUAdn689aCwoqbBJiSnjAK/l8WvCWPIPm49"
                    crossorigin="anonymous"></script>

            <script src="https://stackpath.bootstrapcdn.com/bootstrap/4.1.3/js/bootstrap.min.js"
                    integrity="sha384-ChfqqxuZUCnJSK3+MXmPNIyE6ZbWh2IMqE241rYiqJxyMiZ6OW/JmZQ5stwEULTy"
                    crossorigin="anonymous"></script>

            <link href="https://fonts.googleapis.com/css?family=Merriweather+Sans:800|Merriweather:400,400i,700"
                  rel="stylesheet">

            <meta name="viewport"
                  content="width=device-width, initial-scale=1">
        {% endblock %}

        {% block datatables %}
            {% comment %}
                Requires jquery from above, and uses bootstrap themes
            {% endcomment %}
            <link rel="stylesheet" type="text/css"
                  href="{% static "DataTables-1.10.16/css/dataTables.bootstrap4.min.css" %}"
                  crossorigin="anonymous"/>

            <script type="text/javascript"
                    src="{% static "DataTables-1.10.16/js/jquery.dataTables.min.js" %}"
                    crossorigin="anonymous"></script>

            <script type="text/javascript"
                    src="{% static "DataTables-1.10.16/js/dataTables.bootstrap4.min.js" %}"
                    crossorigin="anonymous"></script>
        {% endblock %}

        {% block fontawesome %}
            <link href="{% static 'fontawesome-5.0.8/css/fontawesome-all.css' %}"
                  rel="stylesheet">
        {% endblock %}

        {% block fileupload %}
            <script type="text/javascript"
                    src="https://cdnjs.cloudflare.com/ajax/libs/blueimp-file-upload/9.19.1/js/jquery.fileupload.min.js"></script>
        {% endblock %}

        {% block jqcookie %}
            <script src="https://cdn.jsdelivr.net/npm/jquery.cookie@1.4.1/jquery.cookie.js"
                    integrity="sha256-uEFhyfv3UgzRTnAZ+SEgvYepKKB0FW6RqZLrqfyUNug="
                    crossorigin="anonymous"></script>
